function navText(obj){return obj?.[LANG]||obj?.pt||''}
const NAV_OPEN_STATE=new Set();
function navNodeContains(node,active){
 if((node.items||[]).includes(active))return true;
 return (node.children||[]).some(child=>navNodeContains(child,active));
}
const SPECIAL_NAV_ITEMS={
 'sql-lab':{icon:'🗄️',title:{pt:'Laboratório de SQL',en:'SQL Lab',es:'Laboratorio de SQL'}},
 'compare-tools':{icon:'⚖️',title:{pt:'Comparador de Ferramentas',en:'Tool Comparator',es:'Comparador de Herramientas'}}
};
function renderNavNode(node,key,depth,active){
 const hasChildren=Array.isArray(node.children)&&node.children.length>0;
 const items=(node.items||[]).filter(k=>DATA[k]||SPECIAL_NAV_ITEMS[k]);
 const contains=navNodeContains(node,active);
 if(contains)NAV_OPEN_STATE.add(key);
 const open=NAV_OPEN_STATE.has(key);
 const inner=hasChildren
   ? node.children.map((child,i)=>renderNavNode(child,`${key}c${i}`,depth+1,active)).join('')
   : items.map(k=>{const sp=SPECIAL_NAV_ITEMS[k];const icon=sp?.icon||topicMeta[k]?.[0]||'•';const title=sp?(sp.title[LANG]||sp.title.pt):navTopicTitle(k,DATA[k][LANG]);return `<a class="tree-link${k===active?' active':''}" data-topic-nav="${k}" href="#/${k}"><span>${icon}</span><span>${title}</span></a>`}).join('');
 return `<div class="tree-node depth-${depth}${open?' open':''}" data-nav-key="${key}"><button class="tree-toggle" type="button" aria-expanded="${open}"><span class="tree-label">${navText(node.label)}</span><span class="tree-plus">${open?'−':'+'}</span></button><div class="tree-children">${inner}</div></div>`;
}
function organizeNavigation(){
 const root=document.getElementById('navTree');if(!root)return;
 const active=location.hash.replace('#/','');
 NAV_V2.forEach((domain,di)=>{if(navNodeContains(domain,active))NAV_OPEN_STATE.add(`d${di}`)});
 root.innerHTML=NAV_V2.map((domain,di)=>{const dk=`d${di}`,dopen=NAV_OPEN_STATE.has(dk);return `<div class="tree-node depth-1${dopen?' open':''}" data-nav-key="${dk}"><button class="tree-toggle" type="button" aria-expanded="${dopen}"><span>${domain.icon}</span><span class="tree-label">${navText(domain.label)}</span><span class="tree-plus">${dopen?'−':'+'}</span></button><div class="tree-children">${domain.children.map((sub,si)=>renderNavNode(sub,`${dk}s${si}`,2,active)).join('')}</div></div>`}).join('');
 root.querySelectorAll('.tree-link[data-topic-nav]').forEach(a=>a.addEventListener('click',e=>{
   if(!window.matchMedia('(max-width: 820px)').matches)return;
   e.preventDefault();
   qaMobileOpenTopic(a.dataset.topicNav);
 }));
 root.querySelectorAll('.tree-toggle').forEach(b=>b.onclick=()=>{
   const n=b.closest('.tree-node'),key=n.dataset.navKey,onBefore=n.classList.contains('open');
   // Accordion entre irmãos: abre o selecionado e recolhe os grupos irmãos.
   if(!onBefore){
     const parent=n.parentElement;
     if(parent)Array.from(parent.children).filter(x=>x!==n&&x.classList?.contains('tree-node')).forEach(sib=>{sib.classList.remove('open');const sk=sib.dataset.navKey;if(sk)NAV_OPEN_STATE.delete(sk);const sb=sib.querySelector(':scope > .tree-toggle');if(sb){sb.setAttribute('aria-expanded','false');const sp=sb.querySelector('.tree-plus');if(sp)sp.textContent='+';}});
   }
   n.classList.toggle('open');const on=n.classList.contains('open');if(on)NAV_OPEN_STATE.add(key);else NAV_OPEN_STATE.delete(key);b.setAttribute('aria-expanded',String(on));b.querySelector('.tree-plus').textContent=on?'−':'+';
 });
}

