function renderToolkit(){
 const L={pt:{title:'QA Toolkit',sub:'Ferramentas rápidas para o dia a dia de Quality Assurance.',pass:'Calculadora de Execução',total:'Total de testes',passed:'Passed',failed:'Failed',blocked:'Blocked',calc:'Calcular',json:'JSON Formatter',format:'Formatar JSON',risk:'Matriz de Risco',prob:'Probabilidade',impact:'Impacto',result:'Resultado'},en:{title:'QA Toolkit',sub:'Quick tools for day-to-day Quality Assurance work.',pass:'Test Execution Calculator',total:'Total tests',passed:'Passed',failed:'Failed',blocked:'Blocked',calc:'Calculate',json:'JSON Formatter',format:'Format JSON',risk:'Risk Matrix',prob:'Probability',impact:'Impact',result:'Result'},es:{title:'QA Toolkit',sub:'Herramientas rápidas para el trabajo diario de Quality Assurance.',pass:'Calculadora de Ejecución',total:'Total de pruebas',passed:'Passed',failed:'Failed',blocked:'Blocked',calc:'Calcular',json:'Formateador JSON',format:'Formatear JSON',risk:'Matriz de Riesgo',prob:'Probabilidad',impact:'Impacto',result:'Resultado'}}[LANG];
 document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${L.title}</div><div class="ico">🧰</div><h1>${L.title}</h1><p>${L.sub}</p></div><div class="tool-grid"><section class="tool-card"><h2>📊 ${L.pass}</h2><div class="mini-grid"><input id="tt" type="number" placeholder="${L.total}"><input id="tp" type="number" placeholder="${L.passed}"><input id="tf" type="number" placeholder="${L.failed}"><input id="tb" type="number" placeholder="${L.blocked}"></div><button class="btn primary" onclick="calcExecution()">${L.calc}</button><div id="execOut" class="tool-output"></div></section><section class="tool-card"><h2>{ } ${L.json}</h2><textarea id="jsonIn" rows="9" placeholder='{"status":"passed"}'></textarea><button class="btn primary" onclick="formatJson()">${L.format}</button><pre id="jsonOut" class="code-output"></pre></section><section class="tool-card"><h2>🎯 ${L.risk}</h2><div class="mini-grid"><select id="riskP"><option value="1">${L.prob}: 1</option><option value="2">${L.prob}: 2</option><option value="3">${L.prob}: 3</option></select><select id="riskI"><option value="1">${L.impact}: 1</option><option value="2">${L.impact}: 2</option><option value="3">${L.impact}: 3</option></select></div><button class="btn primary" onclick="calcRisk()">${L.calc}</button><div id="riskOut" class="tool-output"></div></section></div>`;window.scrollTo(0,0)
}
function calcExecution(){let t=+document.getElementById('tt').value,p=+document.getElementById('tp').value,f=+document.getElementById('tf').value,b=+document.getElementById('tb').value,e=p+f+b;let pct=x=>e?((x/e)*100).toFixed(1):'0.0';document.getElementById('execOut').innerHTML=`<b>${e}/${t||e}</b> executed · ✅ ${pct(p)}% · ❌ ${pct(f)}% · ⛔ ${pct(b)}%`}
function formatJson(){let i=document.getElementById('jsonIn').value,o=document.getElementById('jsonOut');try{o.textContent=JSON.stringify(JSON.parse(i),null,2);o.classList.remove('error')}catch(e){o.textContent=(LANG==='en'?'Invalid JSON: ':LANG==='es'?'JSON inválido: ':'JSON inválido: ')+e.message;o.classList.add('error')}}
function calcRisk(){let p=+document.getElementById('riskP').value,i=+document.getElementById('riskI').value,s=p*i,label=s>=7?(LANG==='en'?'High':LANG==='es'?'Alto':'Alto'):s>=4?(LANG==='en'?'Medium':LANG==='es'?'Medio':'Médio'):(LANG==='en'?'Low':LANG==='es'?'Bajo':'Baixo');document.getElementById('riskOut').innerHTML=`<b>${label}</b> · Score ${s}/9`}
function renderGlossary(){let terms={pt:[['API','Application Programming Interface — interface usada para comunicação entre sistemas.'],['Bug','Defeito observado ou registrado em um produto de software.'],['CI/CD','Integração contínua e entrega/deploy contínuo.'],['Endpoint','Endereço de uma operação disponibilizada por uma API.'],['Flaky test','Teste automatizado que apresenta resultados inconsistentes sem mudança relevante no produto.'],['Regression Testing','Validação de que mudanças não afetaram funcionalidades existentes.'],['UAT','User Acceptance Testing — validação de aceitação pelo negócio/usuário representativo.']],en:[['API','Application Programming Interface — an interface used for communication between systems.'],['Bug','A defect observed or recorded in a software product.'],['CI/CD','Continuous Integration and Continuous Delivery/Deployment.'],['Endpoint','The address of an operation exposed by an API.'],['Flaky test','An automated test that produces inconsistent results without a relevant product change.'],['Regression Testing','Validation that changes did not adversely affect existing functionality.'],['UAT','User Acceptance Testing — acceptance validation by business/end-user representatives.']],es:[['API','Application Programming Interface — interfaz utilizada para la comunicación entre sistemas.'],['Bug','Defecto observado o registrado en un producto de software.'],['CI/CD','Integración Contínua y Entrega/Despliegue Continuo.'],['Endpoint','Dirección de una operación expuesta por una API.'],['Flaky test','Prueba automatizada con resultados inconsistentes sin un cambio relevante en el producto.'],['Regression Testing','Validación de que los cambios no afectaron funcionalidades existentes.'],['UAT','User Acceptance Testing — validación de aceptación por negócio/usuários representativos.']]}[LANG];let title=LANG==='en'?'QA Glossary':LANG==='es'?'Glosario QA':'Glossário QA';document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${title}</div><div class="ico">📚</div><h1>${title}</h1><p>${LANG==='en'?'Quick reference for common Quality Engineering terms.':LANG==='es'?'Referencia rápida de términos comunes de Quality Engineering.':'Referência rápida de termos comuns de Quality Engineering.'}</p></div><div class="glossary-grid">${terms.map(x=>`<article class="glossary-card"><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div>`;window.scrollTo(0,0)}
function askAssistant(){let inp=document.getElementById('chatInput'),q=inp.value.trim();if(!q)return;let terms=q.toLowerCase().split(/\s+/).filter(x=>x.length>2),scores=[];for(let[k,v]of Object.entries(DATA)){let d=v[LANG],txt=[d.title,d.subtitle,d.qa_tip,...d.sections.flat()].join(' ').toLowerCase(),score=terms.reduce((n,w)=>n+(txt.includes(w)?1:0),0);if(score)scores.push([score,k,d])}scores.sort((a,b)=>b[0]-a[0]);let msg=document.getElementById('chatMsg');if(scores.length){let[,k,d]=scores[0];let sec=d.sections[0];msg.innerHTML=`<b>${d.title}</b><br>${sec?sec[1]:d.subtitle}<br><br><button class="btn" onclick="location.hash='#/${k}';document.getElementById('chatbox').classList.remove('open')">${LANG==='en'?'Open topic':LANG==='es'?'Abrir tema':'Abrir tópico'} →</button>`}else msg.textContent=LANG==='en'?'I could not find this topic in the QA Lab knowledge base yet.':LANG==='es'?'Todavía no encontré este tema en la base de QA Lab.':'Ainda não encontrei esse assunto na base do QA Lab.';inp.value=''}


function renderHowToTest(){
 const C={pt:{title:'Como Testar?',sub:'Checklists práticas para transformar uma funcionalidade em ideias de teste.',choose:'Escolha o componente',items:{login:['Credenciais válidas e inválidas','Campos obrigatórios e mensagens','Bloqueio após tentativas, quando aplicável','Recuperação de senha e sessão','Teclado, acessibilidade e responsividade','API: 200/400/401/403 e token','Segurança: brute force, sessão e autorização'],upload:['Arquivo válido e inválido','Limites de tamanho e extensão','Arquivo vazio e corrompido','Nome longo e caracteres especiais','Duplicidade e cancelamento','Interrupção de rede e performance','Segurança: conteúdo malicioso e validação server-side'],checkout:['Carrinho, preço e subtotal','Cupom, frete, endereço e impostos','Usuário convidado e registrado','Pagamento aprovado, recusado e timeout','Duplicidade/idempotência','Integrações com estoque, ERP e pedido','Mobile, acessibilidade e regressão']},tip:'Use a checklist como ponto de partida, não como substituto da análise de risco.'},en:{title:'How to Test?',sub:'Practical checklists to turn a feature into test ideas.',choose:'Choose a component',items:{login:['Valid and invalid credentials','Required fields and messages','Lockout after attempts when applicable','Password recovery and session','Keyboard, accessibility and responsiveness','API: 200/400/401/403 and token','Security: brute force, session and authorization'],upload:['Valid and invalid file','Size and extension limits','Empty and corrupted file','Long name and special characters','Duplicate and cancellation','Network interruption and performance','Security: malicious content and server-side validation'],checkout:['Cart, price and subtotal','Coupon, shipping, address and taxes','Guest and registered user','Approved, declined and timeout payment','Duplicate/idempotency','Inventory, ERP and order integrations','Mobile, accessibility and regression']},tip:'Use the checklist as a starting point, not as a replacement for risk analysis.'},es:{title:'¿Cómo Probar?',sub:'Checklists prácticas para transformar una funcionalidad en ideas de prueba.',choose:'Elija el componente',items:{login:['Credenciales válidas e inválidas','Campos obligatorios y mensajes','Bloqueo tras intentos cuando aplique','Recuperación de contraseña y sesión','Teclado, accesibilidad y responsividad','API: 200/400/401/403 y token','Seguridad: fuerza bruta, sesión y autorización'],upload:['Archivo válido e inválido','Límites de tamaño y extensión','Archivo vacío y corrupto','Nombre largo y caracteres especiales','Duplicidad y cancelación','Interrupción de red y rendimiento','Seguridad: contenido malicioso y validación server-side'],checkout:['Carrito, precio y subtotal','Cupón, envío, dirección e impuestos','Usuario invitado y registrado','Pago aprobado, rechazado y timeout','Duplicidad/idempotencia','Integraciones con inventario, ERP y pedido','Mobile, accesibilidad y regresión']},tip:'Use la checklist como punto de partida, no como sustituto del análisis de riesgo.'}}[LANG];
 let labels={login:'🔐 Login',upload:'📎 Upload',checkout:'🛒 Checkout'};document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${C.title}</div><div class="ico">🧭</div><h1>${C.title}</h1><p>${C.sub}</p></div><section class="tool-card"><h2>${C.choose}</h2><div class="actions">${Object.keys(C.items).map(k=>`<button class="btn" onclick="showChecklist('${k}')">${labels[k]}</button>`).join('')}</div><div id="checkOut" class="checklist-box"></div></section><div class="tip"><b>💡 QA Tip</b><br>${C.tip}</div>`;window._how=C;showChecklist('login');window.scrollTo(0,0)}
function showChecklist(k){let C=window._how,o=document.getElementById('checkOut');if(!C||!o)return;o.innerHTML=`<h3>${k==='login'?'🔐 Login':k==='upload'?'📎 Upload':'🛒 Checkout'}</h3>${C.items[k].map((x,i)=>`<label class="check-row"><input type="checkbox"> <span>${i+1}. ${x}</span></label>`).join('')}`}
function renderApiLab(){const L={pt:['API Lab','Experimente uma requisição simulada e interprete a resposta.','Método','Cenário','Enviar request','Sucesso','Não autorizado','Não encontrado','Erro interno','O QA deve validar status, body, headers, contrato e efeito da operação.'],en:['API Lab','Try a simulated request and interpret the response.','Method','Scenario','Send request','Success','Unauthorized','Not found','Internal error','QA should validate status, body, headers, contract and operation effect.'],es:['API Lab','Pruebe una request simulada e interprete la respuesta.','Método','Escenario','Enviar request','Éxito','No autorizado','No encontrado','Error interno','QA debe validar status, body, headers, contrato y efecto de la operación.']}[LANG];document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › API Lab</div><div class="ico">🔌</div><h1>${L[0]}</h1><p>${L[1]}</p></div><section class="tool-card"><div class="mini-grid"><select id="apiMethod"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select><select id="apiScenario"><option value="200">200 - ${L[5]}</option><option value="401">401 - ${L[6]}</option><option value="404">404 - ${L[7]}</option><option value="500">500 - ${L[8]}</option></select></div><button class="btn primary" onclick="runApiLab()">▶ ${L[4]}</button><pre id="apiOut" class="code-output"></pre></section><div class="tip"><b>🧪 QA</b><br>${L[9]}</div>`;runApiLab();window.scrollTo(0,0)}
function runApiLab(){let s=document.getElementById('apiScenario')?.value||'200',m=document.getElementById('apiMethod')?.value||'GET',map={'200':{status:'200 OK',body:{id:123,name:'QA Lab',active:true}},'401':{status:'401 Unauthorized',body:{error:'authentication_required'}},'404':{status:'404 Not Found',body:{error:'resource_not_found'}},'500':{status:'500 Internal Server Error',body:{error:'unexpected_error'}}},r=map[s];document.getElementById('apiOut').textContent=`${m} /api/resources/123\n${r.status}\ncontent-type: application/json\n\n${JSON.stringify(r.body,null,2)}`}
function renderBugClinic(){const L={pt:['Bug Clinic','Transforme um reporte vago em um defeito reproduzível e útil.','Reporte fraco','Botão não funciona.','Exemplo melhor','Título','Ambiente','Passos','Esperado','Atual','Checkout - botão Finalizar compra não responde após endereço válido','QA / Chrome','1. Abrir checkout  2. Preencher endereço válido  3. Clicar Finalizar compra','O sistema deve avançar para pagamento.','Nada acontece e não há mensagem de erro.'],en:['Bug Clinic','Turn a vague report into a reproducible and useful defect.','Weak report','Button does not work.','Improved example','Title','Environment','Steps','Expected','Actual','Checkout - Place order button does not respond after valid address','QA / Chrome','1. Open checkout  2. Enter valid address  3. Click Place order','The system should proceed to payment.','Nothing happens and no error message is shown.'],es:['Bug Clinic','Transforme un reporte vago en un defecto reproducible y útil.','Reporte débil','El botón no funciona.','Ejemplo mejor','Título','Ambiente','Pasos','Esperado','Actual','Checkout - el botón Finalizar compra no responde tras dirección válida','QA / Chrome','1. Abrir checkout  2. Ingresar dirección válida  3. Hacer clic en Finalizar compra','El sistema debe avanzar al pago.','No ocurre nada y no se muestra mensaje de error.']}[LANG];document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › Bug Clinic</div><div class="ico">🐞</div><h1>${L[0]}</h1><p>${L[1]}</p></div><div class="compare-grid"><article class="bad-card"><h3>❌ ${L[2]}</h3><p>${L[3]}</p></article><article class="good-card"><h3>✅ ${L[4]}</h3><p><b>${L[5]}:</b> ${L[10]}</p><p><b>${L[6]}:</b> ${L[11]}</p><p><b>${L[7]}:</b> ${L[12]}</p><p><b>${L[8]}:</b> ${L[13]}</p><p><b>${L[9]}:</b> ${L[14]}</p></article></div>`;window.scrollTo(0,0)}
function renderQaShop(){const L={pt:['QA Shop','Projeto fictício para praticar o ciclo completo de QA.','User Story','Como cliente, quero aplicar um cupom no carrinho para receber o desconto antes do pagamento.','Critérios de aceite','Cupom válido aplica 10%. Cupom expirado é rejeitado. O desconto não pode ser aplicado duas vezes.','Sua missão','1. Identifique cenários positivos e negativos. 2. Pense em API e regras de negócio. 3. Registre um possível bug. 4. Escolha o que entraria no Smoke e na regressão.'],en:['QA Shop','Fictional project to practice the complete QA cycle.','User Story','As a customer, I want to apply a coupon in the cart so I receive the discount before payment.','Acceptance criteria','A valid coupon applies 10%. An expired coupon is rejected. The discount cannot be applied twice.','Your mission','1. Identify positive and negative scenarios. 2. Consider API and business rules. 3. Record a possible bug. 4. Choose what belongs in Smoke and regression.'],es:['QA Shop','Proyecto ficticio para practicar el ciclo completo de QA.','User Story','Como cliente, quiero aplicar un cupón en el carrito para recibir el descuento antes del pago.','Critérios de aceptación','Un cupón válido aplica 10%. Un cupón vencido es rechazado. El descuento no puede aplicarse dos veces.','Su misión','1. Identifique escenarios positivos y negativos. 2. Considere API y reglas de negócio. 3. Registre un posible bug. 4. Elija qué entra en Smoke y regresión.']}[LANG];document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › QA Shop</div><div class="ico">🏪</div><h1>${L[0]}</h1><p>${L[1]}</p></div><section class="topic-section"><span class="tag">🟢 ${t('level1')}</span><h2>📘 ${L[2]}</h2><p>${L[3]}</p></section><section class="topic-section"><h2>✅ ${L[4]}</h2><p>${L[5]}</p></section><section class="topic-section"><h2>🧪 ${L[6]}</h2><p>${L[7]}</p><div class="actions"><button class="btn" onclick="location.hash='#/how-to-test'">🧭 ${LANG==='en'?'How to Test?':LANG==='es'?'¿Cómo Probar?':'Como Testar?'}</button><button class="btn" onclick="location.hash='#/bug-clinic'">🐞 Bug Clinic</button><button class="btn" onclick="location.hash='#/api-lab'">🔌 API Lab</button></div></section>`;window.scrollTo(0,0)}

