function p14Label(pt,en,es){return LANG==='en'?en:LANG==='es'?es:pt}
function p14Favs(){try{return JSON.parse(localStorage.getItem('qalab-favorites')||'[]')}catch(e){return []}}
function p14IsFav(k){return p14Favs().includes(k)}
function p14ToggleFav(k){let a=p14Favs();a=a.includes(k)?a.filter(x=>x!==k):[...a,k];localStorage.setItem('qalab-favorites',JSON.stringify(a));let b=document.getElementById('favBtn');if(b)b.innerHTML=p14IsFav(k)?'★ '+p14Label('Favoritado','Favorited','Favorito'):'☆ '+p14Label('Adicionar aos favoritos','Add to favorites','Agregar a favoritos');}
function p14Level(n){document.querySelectorAll('.topic-section[data-level]').forEach(s=>{let lv=+s.dataset.level;s.style.display=(n===3||lv<=n)?'block':'none'});document.querySelectorAll('.level-filter button').forEach(b=>b.classList.toggle('active',+b.dataset.level===n));}
function p14Prereqs(k){let ids=(P14_PATHS[k]||[]).filter(x=>DATA[x]);if(!ids.length){let g=topicMeta[k]?.[2];ids=Object.keys(DATA).filter(x=>x!==k&&topicMeta[x]?.[2]===g).slice(0,3)}return ids}
function p14Related(k){let g=topicMeta[k]?.[2];return Object.keys(DATA).filter(x=>x!==k&&topicMeta[x]?.[2]===g).slice(0,6)}
function p14LearningBox(k){let pre=p14Prereqs(k),rel=p14Related(k);let preTitle=p14Label('Recomendado antes','Recommended first','Recomendado antes');let nextTitle=p14Label('Continue estudando','Continue learning','Continúe estudiando');let noPre=p14Label('Você pode começar por este módulo.','You can start with this module.','Puede comenzar por este módulo.');return `<section class="topic-section learning-guide"><span class="tag">🧭 ${p14Label('Trilha','Learning path','Ruta')}</span><h2>${p14Label('Orientação de aprendizado','Learning guidance','Orientación de aprendizaje')}</h2><div class="learning-columns"><div><h3>📌 ${preTitle}</h3>${pre.length?`<div class="related">${pre.map(x=>`<button class="btn" onclick="location.hash='#/${x}'">${topicMeta[x][0]} ${DATA[x][LANG].title}</button>`).join('')}</div>`:`<p>${noPre}</p>`}</div><div><h3>➡️ ${nextTitle}</h3><div class="related">${rel.map(x=>`<button class="btn" onclick="location.hash='#/${x}'">${topicMeta[x][0]} ${DATA[x][LANG].title}</button>`).join('')}</div></div></div></section>`}
const p14OldRenderTopic=renderTopic;
renderTopic=function(k){let d=DATA[k][LANG],meta=topicMeta[k],more=p14Label('Saiba mais','Learn more','Saber más'),collapse=p14Label('Recolher','Collapse','Contraer');let secs=d.sections.map((sec,i)=>{let extra=buildMoreText(d,sec,i),lv=i===0?1:i<3?2:3;return `<section class="topic-section" data-level="${lv}"><span class="tag">${lv===1?'🟢 '+t('level1'):lv===2?'🔵 '+t('level2'):'🟣 '+t('level3')}</span><h2>${sec[0]}</h2><p>${sec[1]}</p><button class="learn-more-btn" type="button" data-more="${more}" data-collapse="${collapse}" onclick="toggleLearnMore(this)">${more} <span class="more-arrow">→</span></button><div class="learn-more-panel">${extra}</div></section>`}).join('');let off=meta[3]?officialLinks(DATA[k]._meta):'';let fav=p14IsFav(k)?'★ '+p14Label('Favoritado','Favorited','Favorito'):'☆ '+p14Label('Adicionar aos favoritos','Add to favorites','Agregar a favoritos');document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${d.title}</div><div class="ico">${meta[0]}</div><h1>${d.title}</h1><p>${d.subtitle}</p><div class="topic-actions"><button id="favBtn" class="btn" onclick="p14ToggleFav('${k}')">${fav}</button></div><div class="topic-meta"><span class="level">🗓 ${t('updated')}</span></div><div class="level-filter"><button class="btn" data-level="1" onclick="p14Level(1)">🟢 ${t('level1')}</button><button class="btn" data-level="2" onclick="p14Level(2)">🔵 ${t('level2')}</button><button class="btn active" data-level="3" onclick="p14Level(3)">🟣 ${t('level3')}</button></div></div>${p14LearningBox(k)}${secs}<div class="tip"><b>💡 ${t('tip')}</b><br>${d.qa_tip}</div>${off}<div class="download-box"><h3>📄 ${t('download')}</h3><p>${p14Label('Baixe o tópico para estudo offline.','Download the topic for offline study.','Descargue el tema para estudiar offline.')}</p><a class="btn primary" href="pdf/${LANG}/${k}.pdf" download>⬇️ ${t('download')}</a></div><section class="topic-section"><h2>🔗 ${p14Label('Conteúdos relacionados','Related content','Contenidos relacionados')}</h2><div class="related">${p14Related(k).map(x=>`<button class="btn" onclick="location.hash='#/${x}'">${topicMeta[x][0]} ${DATA[x][LANG].title}</button>`).join('')}</div></section>`;window.scrollTo(0,0)};
function p14FavoritesPanel(){let a=p14Favs().filter(k=>DATA[k]);if(!a.length)return '';return `<section class="section favorites-section"><div class="section-head"><div><h2>⭐ ${p14Label('Meus favoritos','My favorites','Mis favoritos')}</h2><p>${p14Label('Acesso rápido aos conteúdos salvos neste navegador.','Quick access to content saved in this browser.','Acceso rápido a contenidos guardados en este navegador.')}</p></div></div><div class="related">${a.slice(0,10).map(k=>`<button class="btn" onclick="location.hash='#/${k}'">${topicMeta[k][0]} ${DATA[k][LANG].title}</button>`).join('')}</div></section>`}
const p14OldHome=renderHome;
renderHome=function(){p14OldHome();let main=document.getElementById('main'),fav=p14FavoritesPanel();if(fav){let about=main.querySelector('.about-contact');if(about)about.insertAdjacentHTML('beforebegin',fav);else main.insertAdjacentHTML('beforeend',fav)}};


