  'bug-clinic':{icon:'🐞',pt:['Clínica de Bugs','Treine investigação e escrita de defeitos claros, reproduzíveis e úteis.'],en:['Bug Clinic','Train investigation and clear, reproducible, useful defect reporting.'],es:['Clínica de Bugs','Entrene investigación y registro de defectos claros, reproducibles y útiles.']},
