function p17GlossaryBox(k){let d=DATA[k]?.[LANG];if(!d)return '';let text=[d.title,d.subtitle,d.qa_tip,...d.sections.flat()].join(' ').toLowerCase(),dict=P17_GLOSSARY[LANG],found=Object.entries(dict).filter(([term])=>text.includes(term.toLowerCase())).slice(0,8);if(!found.length)return '';let title=LANG==='en'?'Terms in this topic':LANG==='es'?'Términos en este tema':'Termos neste conteúdo';let all=LANG==='en'?'Open full glossary':LANG==='es'?'Abrir glosario completo':'Abrir glossário completo';return `<section class="topic-section contextual-glossary"><span class="tag">📚 Glossário</span><h2>${title}</h2><div class="glossary-chips">${found.map(([term,desc])=>`<details class="glossary-chip"><summary>${term}</summary><p>${desc}</p></details>`).join('')}</div><button class="btn" onclick="location.hash='#/glossary'">📚 ${all}</button></section>`}
